 if(!groups.some(group=>group.key===relatedAudioTab))relatedAudioTab=groups[0].key;const section=el('section',undefined,'related-audio'),heading=el('h3',context.name+' · 音频'),tabs=el('nav',undefined,'related-audio-tabs'),list=el('div',undefined,'related-audio-list');section.dataset.character=result.character;section.setAttribute('aria-label','角色相关音频');tabs.setAttribute('role','tablist');tabs.setAttribute('aria-label','角色音频分类');list.setAttribute('role','tabpanel');const paint=()=>{for(const button of tabs.children)button.setAttribute('aria-selected',String(button.dataset.category===relatedAudioTab));list.replaceChildren(...groups.find(group=>group.key===relatedAudioTab).clips.map(clip=>audioAsset(clip,true)));};for(const group of groups){const button=el('button',group.label);button.dataset.category=group.key;button.setAttribute('role','tab');button.onclick=()=>{relatedAudioTab=group.key;paint();};tabs.append(button);}section.append(heading,tabs,list);paint();return section;
